"""Static validation of webhook.py without importing flask/stripe.

Parses the source, confirms the required route and handlers exist, and
verifies signature verification + idempotency helpers are present.
"""

import ast
import sys

PATH = "webhook.py"


def main():
    with open(PATH, "r", encoding="utf-8") as fh:
        source = fh.read()
    tree = ast.parse(source, filename=PATH)

    defined = {node.name for node in tree.body if isinstance(node, (ast.FunctionDef, ast.ClassDef))}
    route_decorated = []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            for dec in node.decorator_list:
                if isinstance(dec, ast.Call) and getattr(dec.func, "id", "") == "app.route":
                    route_decorated.append(node.name)

    checks = {
        "route /webhook registered": route_decorated == ["webhook"],
        "handler payment_intent.succeeded": "handle_payment_succeeded" in defined,
        "handler payment_intent.payment_failed": "handle_payment_failed" in defined,
        "signature verification helper": "verify_webhook_signature" in defined,
        "idempotency helper": "is_event_processed" in defined and "mark_event_processed" in defined,
        "uses construct_event": "construct_event" in source,
    }

    failures = [name for name, ok in checks.items() if not ok]
    for name, ok in checks.items():
        print(f"{'PASS' if ok else 'FAIL'}  {name}")

    if failures:
        print(f"Validation failed: {failures}")
        return 1
    print("Validation passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

